/* The tables of M18 · Results and report cards. */

/** How a result is worked out. A school usually has two: primary classes and board classes. */
export const resultPolicies = defineTable(
  'result_policies',
  { module: 'M18', scope: 'org' },
  {
    ...baseColumns,
    name: text().notNull(),
    /** the grades it applies to */
    gradeIds: uuid().array().notNull(),
    passRule: enumText(resultPolicyPassRules).notNull().default('every_subject'),
    minAggregatePercent: decimal(5, 2).notNull().default(40),
    /** theory and practical each need their own pass marks */
    componentsPassSeparately: boolean().notNull().default(true),
    /** failing up to this many subjects gives `compartment` instead of `fail` */
    compartmentMaxSubjects: integer().notNull().default(0),
    /** the most that can be added across subjects */
    graceMarksTotal: decimal(5, 2).notNull().default(0),
    graceMarksPerSubject: decimal(5, 2).notNull().default(0),
    graceMaxSubjects: integer().notNull().default(0),
    /** dense gives 1, 1, 2; competition gives 1, 1, 3 */
    positionMethod: enumText(resultPolicyPositionMethods).notNull().default('dense'),
    positionScope: enumText(resultPolicyPositionScopes).notNull().default('section'),
    positionsNeedPass: boolean().notNull().default(true),
    percentDecimals: integer().notNull().default(2),
    isActive: boolean().notNull().default(true),
  },
  (t) => [
    between('result_policies', t.minAggregatePercent, 0, 100),
    nonNegative('result_policies', t.compartmentMaxSubjects),
    nonNegative('result_policies', t.graceMarksTotal),
    nonNegative('result_policies', t.graceMarksPerSubject),
    nonNegative('result_policies', t.graceMaxSubjects),
    between('result_policies', t.percentDecimals, 0, 2),
    uniqueIndex('result_policies_name_uq').on(t.orgId, t.name).where(live(t)),
  ],
);

/** One published thing: the result of an exam, a term or a year for some grades. */
export const resultSets = defineTable(
  'result_sets',
  { module: 'M18', scope: 'branch', member: { read: { status: 'published' } } },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    academicYearId: uuid()
      .references((): AnyPgColumn => academicYears.id)
      .notNull(),
    termId: uuid().references((): AnyPgColumn => terms.id),
    kind: enumText(resultSetKinds).notNull(),
    /** "First term result 2026" */
    name: text().notNull(),
    /** required for kind `exam` */
    examId: uuid().references((): AnyPgColumn => exams.id),
    gradeIds: uuid().array().notNull(),
    policyId: uuid()
      .references((): AnyPgColumn => resultPolicies.id)
      .notNull(),
    gradingSchemeId: uuid()
      .references((): AnyPgColumn => gradingSchemes.id)
      .notNull(),
    /** the policy and grade bands copied at publish */
    frozenRules: jsonb(),
    templateId: uuid().references((): AnyPgColumn => reportCardTemplates.id),
    status: enumText(resultSetStatuses).notNull().default('draft'),
    computedAt: timestamptz(),
    /** scheduled publishing */
    publishAt: timestamptz(),
    publishedAt: timestamptz(),
    publishedBy: uuid().references((): AnyPgColumn => profiles.id),
    showPositions: boolean().notNull().default(true),
  },
  (t) => [
    check('result_sets_exam_id_needed', sql`${t.kind} <> 'exam' or ${t.examId} is not null`),
    uniqueIndex('result_sets_branch_academic_year_name_uq')
      .on(t.branchId, t.academicYearId, t.name)
      .where(live(t)),
  ],
);

/** For a term or annual result: which exams it combines and with what weight. */
export const resultSetComponents = defineTable(
  'result_set_components',
  { module: 'M18', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    resultSetId: uuid()
      .references((): AnyPgColumn => resultSets.id)
      .notNull(),
    examId: uuid()
      .references((): AnyPgColumn => exams.id)
      .notNull(),
    /** the set's weights total 100 */
    weightPercent: decimal(5, 2).notNull(),
  },
  (t) => [
    positive('result_set_components', t.weightPercent),
    check('result_set_components_weight_percent_max', sql`${t.weightPercent} <= 100`),
    uniqueIndex('result_set_components_result_set_exam_uq')
      .on(t.resultSetId, t.examId)
      .where(live(t)),
  ],
);

/** One student's result in one result set. */
export const results = defineTable(
  'results',
  { module: 'M18', scope: 'branch', family: 'studentId', custom: true },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    resultSetId: uuid()
      .references((): AnyPgColumn => resultSets.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    enrollmentId: uuid()
      .references((): AnyPgColumn => enrollments.id)
      .notNull(),
    /** the section at computation */
    sectionId: uuid()
      .references((): AnyPgColumn => sections.id)
      .notNull(),
    totalObtained: decimal(8, 2).notNull(),
    totalMax: decimal(8, 2).notNull(),
    graceMarks: decimal(5, 2).notNull().default(0),
    percent: decimal(5, 2).notNull(),
    gradeLetter: text(),
    gradePoint: decimal(4, 2),
    outcome: enumText(resultOutcomes).notNull(),
    failedSubjects: integer().notNull().default(0),
    positionSection: integer(),
    positionGrade: integer(),
    daysPresent: integer(),
    daysTotal: integer(),
    teacherRemark: text(),
    teacherRemarkUr: text(),
    headRemark: text(),
    remarkSource: enumText(resultRemarkSources).notNull().default('none'),
    isWithheld: boolean().notNull().default(false),
    withheldReason: enumText(resultWithheldReasons),
    /** shown to the guardian */
    withheldNote: text(),
    /** goes up when recomputed after publishing */
    revision: integer().notNull().default(1),
  },
  (t) => [
    nonNegative('results', t.failedSubjects),
    positive('results', t.revision),
    uniqueIndex('results_result_set_student_uq').on(t.resultSetId, t.studentId).where(live(t)),
    index('results_student_idx').on(t.orgId, t.studentId),
    index('results_result_set_section_percent_idx').on(
      t.orgId,
      t.resultSetId,
      t.sectionId,
      t.percent,
    ),
    customPolicy('results_follows_set', {
      for: 'select',
      restrictive: true,
      using: sql`${policySql.isStaff} or exists (select 1 from result_sets p where p.id = ${t.resultSetId})`,
    }),
  ],
);

export const resultSubjects = defineTable(
  'result_subjects',
  { module: 'M18', scope: 'branch', family: 'studentId', custom: true },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    resultId: uuid()
      .references((): AnyPgColumn => results.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    gradeSubjectId: uuid()
      .references((): AnyPgColumn => gradeSubjects.id)
      .notNull(),
    /** copied, so a later rename does not change an issued result */
    subjectName: text().notNull(),
    theoryObtained: decimal(6, 2),
    theoryMax: decimal(6, 2),
    practicalObtained: decimal(6, 2),
    practicalMax: decimal(6, 2),
    obtained: decimal(6, 2).notNull(),
    max: decimal(6, 2).notNull(),
    graceMarks: decimal(5, 2).notNull().default(0),
    percent: decimal(5, 2).notNull(),
    gradeLetter: text(),
    gradePoint: decimal(4, 2),
    status: enumText(resultSubjectStatuses).notNull(),
    /** highest in subject */
    positionSection: integer(),
  },
  (t) => [
    uniqueIndex('result_subjects_result_grade_subject_uq')
      .on(t.resultId, t.gradeSubjectId)
      .where(live(t)),
    customPolicy('result_subjects_follows_result', {
      for: 'select',
      restrictive: true,
      using: sql`${policySql.isStaff} or exists (select 1 from results p where p.id = ${t.resultId} and not p.is_withheld)`,
    }),
  ],
);

export const reportCardTemplates = defineTable(
  'report_card_templates',
  { module: 'M18', scope: 'org' },
  {
    ...baseColumns,
    name: text().notNull(),
    layout: enumText(reportCardTemplateLayouts).notNull(),
    language: enumText(reportCardTemplateLanguages).notNull().default('en'),
    /** show positions, attendance, co-scholastic, bar chart, previous terms, grading key, signature labels */
    options: jsonb().notNull().default({}),
    /** empty means all */
    gradeIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
    isDefault: boolean().notNull().default(false),
    status: enumText(reportCardTemplateStatuses).notNull().default('draft'),
  },
  (t) => [uniqueIndex('report_card_templates_name_uq').on(t.orgId, t.name).where(live(t))],
);

export const reportCards = defineTable(
  'report_cards',
  {
    module: 'M18',
    scope: 'branch',
    family: 'studentId',
    custom: true,
    familyRule: { read: { status: 'generated' }, update: { status: 'generated' } },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    resultId: uuid()
      .references((): AnyPgColumn => results.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    templateId: uuid()
      .references((): AnyPgColumn => reportCardTemplates.id)
      .notNull(),
    /** matches the result's revision */
    revision: integer().notNull(),
    /** empty until generated */
    documentId: uuid().references((): AnyPgColumn => generatedDocuments.id),
    status: enumText(reportCardStatuses).notNull().default('pending'),
    /** the guardian */
    acknowledgedBy: uuid().references((): AnyPgColumn => profiles.id),
    acknowledgedAt: timestamptz(),
  },
  (t) => [
    positive('report_cards', t.revision),
    uniqueIndex('report_cards_result_revision_uq').on(t.resultId, t.revision).where(live(t)),
    customPolicy('report_cards_follows_result', {
      for: 'all',
      restrictive: true,
      using: sql`${policySql.isStaff} or exists (select 1 from results p where p.id = ${t.resultId} and not p.is_withheld)`,
      withCheck: sql`${policySql.isStaff} or exists (select 1 from results p where p.id = ${t.resultId} and not p.is_withheld)`,
    }),
  ],
);

